// 감시할 레포. 늘리려면 여기에 한 줄 추가하면 된다.
return [
  { json: { owner: 'seongj-un', repo: 'duri' } },
  { json: { owner: 'seongj-un', repo: 'Docs_RAG' } },
];

// GitHub Actions 런 결과를 레포별 상태 기계로 판정한다.
// staticData 에 레포마다 { lastRunId, lastConclusion } 을 들고 간다.
//   - 최초 실행은 기준선만 잡고 침묵한다. 과거 이력이 한꺼번에 쏟아지는 것을 막는다.
//   - cancelled/skipped 는 건강 상태를 말해주지 않으므로 lastConclusion 을 건드리지 않는다.
//     concurrency 의 cancel-in-progress 때문에 실제로 자주 발생한다.
const store = $getWorkflowStaticData('global');
if (!store.ci) store.ci = {};

const FAILED = new Set(['failure', 'timed_out', 'startup_failure', 'action_required']);
const targets = $('CI 감시 대상').all();
const out = [];

$input.all().forEach((item, index) => {
  const runs = item.json.workflow_runs ?? [];
  if (runs.length === 0) return;

  // API 가 최신순으로 주지만 순서에 기대지 않고 명시적으로 최신을 고른다.
  const run = runs.reduce((a, b) => (b.id > a.id ? b : a));

  const target = targets[index]?.json;
  const key = run.repository?.full_name ?? (target ? target.owner + '/' + target.repo : null);
  if (!key) return;

  const prev = store.ci[key];

  // 최초 실행: 기준선만 저장하고 알리지 않는다.
  if (!prev) {
    store.ci[key] = { lastRunId: run.id, lastConclusion: run.conclusion };
    return;
  }
  if (run.id === prev.lastRunId) return; // 변화 없음

  const conclusion = run.conclusion;

  // 취소/스킵은 건강 신호가 아니다. 봤다는 표시만 남기고 결론은 유지한다.
  if (conclusion === 'cancelled' || conclusion === 'skipped') {
    store.ci[key] = { lastRunId: run.id, lastConclusion: prev.lastConclusion };
    return;
  }

  const wasBroken = FAILED.has(prev.lastConclusion);
  const isBroken = FAILED.has(conclusion);
  store.ci[key] = { lastRunId: run.id, lastConclusion: conclusion };

  let header = null;
  if (isBroken) header = '🔴 **CI 실패** · ' + key;
  else if (conclusion === 'success' && wasBroken) header = '🟢 **CI 복구** · ' + key;
  if (!header) return; // 성공이 이어지는 중 — 침묵

  // 커밋 메시지는 여러 문단짜리라 첫 줄만 쓴다.
  const subject = (run.head_commit?.message ?? '').split('\n')[0] || '(커밋 메시지 없음)';
  const author = run.head_commit?.author?.name ?? run.actor?.login ?? 'unknown';
  const sha = (run.head_sha ?? '').slice(0, 7);

  out.push({
    json: {
      kind: isBroken ? 'ci_failure' : 'ci_recovered',
      repo: key,
      discordMessage: [
        header,
        '**' + subject + '**',
        '`' + sha + '` · ' + author + ' · run #' + run.run_number + ' · `' + conclusion + '`',
        run.html_url,
      ].join('\n'),
    },
    pairedItem: { item: index },
  });
});

return out;

// 감시할 배포 엔드포인트. 늘리려면 여기에 한 덩어리 추가하면 된다.
//   expect: 'spa-shell'   → 200 + 본문에 markers 가 전부 있어야 정상
//           'json-status' → 200 + 본문 JSON 의 status 가 'UP' 이어야 정상
return [
  {
    json: {
      name: 'duri 프론트 (Vercel)',
      url: 'https://pairpay-two.vercel.app',
      expect: 'spa-shell',
      // vercel.json 의 rewrite 가 없는 경로까지 200 + index.html 로 돌려준다.
      // 상태코드만 보면 앱이 망가져도 정상으로 읽히므로 본문 마커까지 확인한다.
      markers: ['id="root"', '/assets/index-'],
    },
  },
];

// 배포된 서비스가 실제로 살아있는지 판정한다.
// 한 번 실패했다고 바로 알리지 않는다 — 순간적인 네트워크 오류로 알림이 요동치는 걸 막는다.
// STRIKES 회 연속 실패해야 다운으로 본다 (5분 주기 × 2 = 최대 10분 지연).
// 더 빨리 알고 싶으면 1 로 낮추면 된다.
const STRIKES = 2;

const store = $getWorkflowStaticData('global');
if (!store.health) store.health = {};

const targets = $('헬스체크 대상').all();
const out = [];

$input.all().forEach((item, index) => {
  const target = targets[index]?.json;
  if (!target) return;

  const res = item.json ?? {};
  const status = res.statusCode;
  // fullResponse + responseFormat:'text' 은 본문을 body 가 아니라 data 에 담는다.
  // body 로 읽으면 항상 빈 문자열이 돼서 정상인 사이트를 다운으로 오판한다.
  const raw = res.data ?? res.body;
  const body = typeof raw === 'string' ? raw : '';

  // ── 우리 쪽 장애를 남의 장애로 오진하지 않는다 (2026-09-28) ─────────────────
  // 2026-09-28 00:04 에 `duri 프론트` 가 "배포 다운" 으로 잡혔는데 사이트는 멀쩡했다
  // (그날 낮 실측 HTTP 200). 사유가 `getaddrinfo ENOTFOUND pairpay-two.vercel.app` 였고,
  // 같은 순간 디스코드 전송도 `ENOTFOUND discord.com` 으로 죽었다 — 맥북이 자느라
  // **이쪽 DNS 가 죽은** 것이다. 디스코드도 같이 죽어서 우연히 오알림이 안 나갔을 뿐이다.
  //
  // 이름이 안 풀리는 것은 상대의 장애가 아니다. 상대가 실제로 죽으면 5xx 나 연결 거부가
  // 오지 DNS 해석이 실패하지는 않는다. 그래서 **판단 불가**로 보고 침묵한다 —
  // strikes 를 올리지도, 0 으로 되돌리지도 않고 상태를 그대로 둔다.
  //
  // `헬스 요청` 의 onError:continueRegularOutput 만으로는 못 막았다. 오류 항목이 그대로
  // 여기로 흘러와 strike 로 세어졌기 때문이다 — 막는 자리는 전송이 아니라 **판정**이다.
  const errText = res.error == null ? ''
    : (typeof res.error === 'string' ? res.error : JSON.stringify(res.error));
  if (/ENOTFOUND|EAI_AGAIN|EAI_NODATA|ENETDOWN|ENETUNREACH/i.test(errText)) return;

  // 왜 실패로 봤는지를 사람이 읽을 수 있게 남긴다.
  let reason = null;
  if (res.error) {
    const e = res.error;
    reason = '요청 실패 — ' + (typeof e === 'string' ? e : (e.message ?? '알 수 없는 오류'));
  } else if (status !== 200) {
    reason = 'HTTP ' + (status ?? '응답 없음');
  } else if (target.expect === 'spa-shell') {
    const missing = (target.markers ?? []).filter((m) => !body.includes(m));
    if (missing.length) {
      reason = '200 이지만 본문에 ' + missing.map((m) => '`' + m + '`').join(', ') + ' 없음';
    }
  } else if (target.expect === 'json-status') {
    let parsed = null;
    try { parsed = JSON.parse(body); } catch (err) { parsed = null; }
    if (!parsed) reason = '200 이지만 본문이 JSON 이 아님';
    else if (parsed.status !== 'UP') reason = 'status=' + (parsed.status ?? '없음');
  }

  const key = target.name;
  const prev = store.health[key] ?? { down: false, strikes: 0 };

  if (reason) {
    const strikes = prev.strikes + 1;
    store.health[key] = { down: prev.down || strikes >= STRIKES, strikes };
    // 아직 기준 미달이거나 이미 다운을 알렸으면 다시 알리지 않는다.
    if (prev.down || strikes < STRIKES) return;
    out.push({
      json: {
        kind: 'health_down',
        target: key,
        discordMessage: [
          '🔴 **배포 다운** · ' + key,
          target.url,
          '사유: ' + reason,
          STRIKES + '회 연속 실패 확인',
        ].join('\n'),
      },
      pairedItem: { item: index },
    });
    return;
  }

  // 정상 응답.
  store.health[key] = { down: false, strikes: 0 };
  if (!prev.down) return; // 계속 정상이었음 — 침묵
  out.push({
    json: {
      kind: 'health_up',
      target: key,
      discordMessage: [
        '🟢 **배포 복구** · ' + key,
        target.url,
        '정상 응답 확인 (HTTP ' + status + ')',
      ].join('\n'),
    },
    pairedItem: { item: index },
  });
});

return out;

// 디스코드 전송이 **실패한** 항목만 통과시킨다.
//
// 이 n8n(2.36.9)의 Discord 노드는 `onError: continueErrorOutput` 을 걸어도 오류 항목을
// main[1] 이 아니라 **main[0](정상 출력)** 으로 내보낸다 — 2026-09-18 실측:
//   data.main = [ [{json:{error:"...", description:"connect ECONNREFUSED ..."}}], [] ]
// 그래서 두 출력을 모두 이 노드로 모으고, 여기서 오류 모양인 것만 고른다.
// 버전이 바뀌어 main[1] 로 오게 되더라도 똑같이 걸린다 — 어느 쪽으로 오든 상관없다.
//
// 성공 항목에는 error 키가 없으므로 그대로 걸러진다(= 아래로 아무것도 안 내려간다).
return $input.all().filter((i) => i && i.json && i.json.error);
